INSERT INTO OP_MENU_SELLER (
	MENU_ID, MENU_PARENT_ID, MENU_TYPE, MENU_NAME, MENU_CODE, MENU_URL, MENU_SEQ, DISPLAY_FLAG, STATUS_CODE
)
