mapper.insert:
INSERT INTO OP_COMMON_MESSAGE (
	ID, `LANGUAGE`, MESSAGE
)
VALUES (
	'MENU_'||#{menuId}, 'ko', #{menuName}
)

mapper.update:
UPDATE OP_COMMON_MESSAGE
SET MESSAGE  = #{menuName}
WHERE ID = 'MENU_'||#{menuId}
AND `LANGUAGE` = 'ko'

mapper.delete:
DELETE FROM OP_COMMON_MESSAGE
WHERE ID = 'MENU_'||#{menuId}
AND `LANGUAGE` = 'ko'
